    "item sprites" to Tr(ja = "どうぐの え", fr = "les sprites d'objets", de = "die Item-Sprites", it = "gli sprite degli strumenti", es = "los sprites de objetos", br = "os sprites de itens", pt = "os sprites de itens", ko = "도구 그림"),
    "Looks like {0}, from the names in the ROM. Read as that until you have a POKéMON to check it by." to Tr(ja = "ROMの なまえから {0}の ようです。 ポケモンを てにいれて たしかめるまで そう よみます。", fr = "Ressemble à {0}, d'après les noms de la ROM. Lu ainsi jusqu'à ce que vous ayez un POKéMON pour vérifier.", de = "Sieht nach den Namen im ROM wie {0} aus. So gelesen, bis ein POKéMON es bestätigen kann.", it = "Sembra {0}, dai nomi nella ROM. Letto così finché non avrai un POKéMON per verificarlo.", es = "Parece {0}, por los nombres de la ROM. Se lee así hasta que tengas un POKéMON para comprobarlo.", br = "Parece {0}, pelos nomes na ROM. Lido assim até você ter um POKéMON para verificar.", pt = "Parece {0}, pelos nomes na ROM. Lido assim até ter um POKéMON para verificar.", ko = "ROM 속 이름으로 보면 {0} 같아요. 포켓몬을 얻어 확인할 때까지 그렇게 인식해요."),
    "Read as {0}: its party and names checked out against this ROM. Off: {1}. The library tags it PARTIALLY SUPPORTED." to Tr(ja = "{0}として よみます: てもちと なまえは この ROMと あいました。 オフ: {1}。 ライブラリでは 「いちぶ たいおう」です。", fr = "Lu comme {0} : équipe et noms vérifiés sur cette ROM. Désactivé : {1}. La bibliothèque l'indique PARTIEL.", de = "Gelesen als {0}: Team und Namen passen zu diesem ROM. Aus: {1}. Die Bibliothek markiert es als TEILWEISE.", it = "Letto come {0}: squadra e nomi verificati su questa ROM. Spento: {1}. La libreria lo segna PARZIALE.", es = "Leído como {0}: equipo y nombres comprobados en esta ROM. Desactivado: {1}. La biblioteca lo marca PARCIAL.", br = "Lido como {0}: equipe e nomes verificados nesta ROM. Desativado: {1}. A biblioteca o marca como PARCIAL.", pt = "Lido como {0}: equipe e nomes verificados nesta ROM. Desativado: {1}. A biblioteca marca-o como PARCIAL.", ko = "인식된 게임: {0}. 파티와 이름이 이 ROM과 맞아요. 꺼짐: {1}. 라이브러리에서는 일부 지원으로 표시돼요."),
    "Your party doesn't read as {0} - it does as {1}. Pick the game you're playing." to Tr(ja = "てもちが {0}として よめません - {1}なら よめます。 あそんでいる ゲームを えらんでください。", fr = "Votre équipe ne se lit pas comme {0} - mais comme {1}. Choisissez votre jeu.", de = "Dein Team liest sich nicht als {0} - aber als {1}. Wähle dein Spiel.", it = "La tua squadra non si legge come {0} - ma come {1}. Scegli il tuo gioco.", es = "Tu equipo no se lee como {0} - pero sí como {1}. Elige tu juego.", br = "Sua equipe não é lida como {0} - e sim como {1}. Escolha o seu jogo.", pt = "A sua equipe não é lida como {0} - mas sim como {1}. Escolha o seu jogo.", ko = "파티가 {0}에는 맞지 않고 {1}에 맞아요. 플레이 중인 게임을 골라 주세요."),
    "Your party doesn't read as {0}: names and sprites may be wrong. Pick the game you're playing, or keep it." to Tr(ja = "てもちが {0}として よめません: なまえや えが ちがうかも。 あそんでいる ゲームを えらぶか このままに。", fr = "Votre équipe ne se lit pas comme {0} : noms et sprites peuvent être faux. Choisissez votre jeu, ou gardez-le.", de = "Dein Team liest sich nicht als {0}: Namen und Sprites können falsch sein. Wähle dein Spiel oder behalte es.", it = "La tua squadra non si legge come {0}: nomi e sprite potrebbero essere sbagliati. Scegli il tuo gioco, o tienilo.", es = "Tu equipo no se lee como {0}: nombres y sprites pueden fallar. Elige tu juego o mantenlo.", br = "Sua equipe não é lida como {0}: nomes e sprites podem estar errados. Escolha o seu jogo, ou mantenha.", pt = "A sua equipe não é lida como {0}: nomes e sprites podem estar errados. Escolha o seu jogo, ou mantenha-o.", ko = "파티가 {0}에 맞지 않아요: 이름과 그림이 틀릴 수 있어요. 플레이 중인 게임을 고르거나 그대로 두세요."),
    "You said it's none of the games PokéDaisy knows. If it's a version of one, pick it." to Tr(ja = "PokéDaisyの しる ゲームでは ないと えらびました。 どれかの バージョンなら えらんでください。", fr = "Vous avez dit que ce n'est aucun des jeux connus de PokéDaisy. Si c'en est une version, choisissez-le.", de = "Du hast gesagt, es ist keines der Spiele, die PokéDaisy kennt. Ist es eine Version davon, wähle es.", it = "Hai detto che non è nessuno dei giochi noti a PokéDaisy. Se ne è una versione, sceglilo.", es = "Dijiste que no es ninguno de los juegos que conoce PokéDaisy. Si es una versión de uno, elígelo.", br = "Você disse que não é nenhum dos jogos que o PokéDaisy conhece. Se for uma versão de um deles, escolha-o.", pt = "Disse que não é nenhum dos jogos que o PokéDaisy conhece. Se for uma versão de um deles, escolha-o.", ko = "PokéDaisy가 아는 게임이 아니라고 골랐어요. 그중 하나의 버전이라면 골라 주세요."),
    "the POKéDEX" to Tr(ja = "ずかん", fr = "le POKéDEX", de = "der POKéDEX", it = "il POKéDEX", es = "la POKéDEX", br = "a POKéDEX", pt = "a POKéDEX", ko = "도감"),
    "the GUIDE's live pages" to Tr(ja = "ガイドの ライブページ", fr = "les pages en direct du GUIDE", de = "die Live-Seiten des GUIDES", it = "le pagine dal vivo della GUIDA", es = "las páginas en vivo de la GUÍA", br = "as páginas ao vivo do GUIA", pt = "as páginas em direto do GUIA", ko = "가이드의 실시간 페이지"),
    "item descriptions" to Tr(ja = "どうぐの せつめい", fr = "les descriptions d'objets", de = "die Item-Beschreibungen", it = "le descrizioni degli strumenti", es = "las descripciones de objetos", br = "as descrições de itens", pt = "as descrições de itens", ko = "도구 설명"),
    "Read as {0}: everything matched, so it works like a supported game." to Tr(ja = "{0}として よみます: すべて あったので サポートずみと おなじです。", fr = "Lu comme {0} : tout correspond, il marche comme un jeu pris en charge.", de = "Gelesen als {0}: alles passt, es läuft wie ein unterstütztes Spiel.", it = "Letto come {0}: tutto combacia, funziona come un gioco supportato.", es = "Leído como {0}: todo encaja, funciona como un juego compatible.", br = "Lido como {0}: tudo confere, então funciona como um jogo suportado.", pt = "Lido como {0}: tudo corresponde, por isso funciona como um jogo suportado.", ko = "인식된 게임: {0}. 모두 맞아서 지원 게임처럼 작동해요."),
    "BLOCKED" to Tr(ja = "ブロック", fr = "BLOQUÉ", de = "GESPERRT", it = "BLOCCATO", es = "BLOQUEADO", br = "BLOQUEADO", pt = "BLOQUEADO", ko = "차단됨"),
    "Removed at its developer's request" to Tr(ja = "せいさくしゃの いらいで はずしました", fr = "Retiré à la demande de son développeur", de = "Auf Wunsch des Entwicklers entfernt", it = "Rimosso su richiesta del suo sviluppatore", es = "Retirado a petición de su desarrollador", br = "Removido a pedido do desenvolvedor", pt = "Removido a pedido do programador", ko = "개발자 요청으로 제거됨"),
    "NOT AVAILABLE" to Tr(ja = "りよう できません", fr = "INDISPONIBLE", de = "NICHT VERFÜGBAR", it = "NON DISPONIBILE", es = "NO DISPONIBLE", br = "INDISPONÍVEL", pt = "INDISPONÍVEL", ko = "사용할 수 없음"),
    "OPEN DISCORD" to Tr(ja = "Discordを ひらく", fr = "OUVRIR DISCORD", de = "DISCORD ÖFFNEN", it = "APRI DISCORD", es = "ABRIR DISCORD", br = "ABRIR DISCORD", pt = "ABRIR DISCORD", ko = "디스코드 열기"),
    "The game still plays on its own, without the companion." to Tr(ja = "ゲームは コンパニオン なしで そのまま あそべます。", fr = "Le jeu reste jouable seul, sans le compagnon.", de = "Das Spiel läuft weiter, nur ohne den Begleiter.", it = "Il gioco funziona comunque da solo, senza il compagno.", es = "El juego sigue funcionando solo, sin el acompañante.", br = "O jogo continua funcionando sozinho, sem o companheiro.", pt = "O jogo continua a funcionar sozinho, sem o companheiro.", ko = "게임은 컴패니언 없이 그대로 플레이할 수 있어요."),
    "Ghost Grey's developer asked for it to be removed from PokéDaisy. If you'd like it supported again, please contact the Ghost Grey developer on their Discord." to Tr(ja = "Ghost Greyの せいさくしゃから PokéDaisyから はずすよう たのまれました。 また たいおうして ほしい ときは Ghost Greyの Discordで せいさくしゃに れんらく してください。", fr = "Le développeur de Ghost Grey a demandé qu'il soit retiré de PokéDaisy. Si vous souhaitez qu'il soit de nouveau pris en charge, contactez le développeur de Ghost Grey sur son Discord.", de = "Der Entwickler von Ghost Grey hat darum gebeten, es aus PokéDaisy zu entfernen. Wenn du es wieder unterstützt haben möchtest, wende dich auf dem Discord von Ghost Grey an den Entwickler.", it = "Lo sviluppatore di Ghost Grey ha chiesto di rimuoverlo da PokéDaisy. Se vuoi che torni a essere supportato, contatta lo sviluppatore di Ghost Grey sul suo Discord.", es = "El desarrollador de Ghost Grey pidió que se retirara de PokéDaisy. Si quieres que vuelva a ser compatible, contacta con el desarrollador de Ghost Grey en su Discord.", br = "O desenvolvedor de Ghost Grey pediu que ele fosse removido do PokéDaisy. Se você quiser que ele volte a ser suportado, fale com o desenvolvedor de Ghost Grey no Discord dele.", pt = "O programador de Ghost Grey pediu que fosse removido do PokéDaisy. Se quiser que volte a ser suportado, contacte o programador de Ghost Grey no Discord dele.", ko = "Ghost Grey 개발자가 PokéDaisy에서 빼 달라고 요청했어요. 다시 지원되길 원하면 Ghost Grey 디스코드에서 개발자에게 문의해 주세요."),
    "ASK FOR SUPPORT" to Tr(ja = "サポートを たのむ", fr = "DEMANDER LE SUPPORT", de = "SUPPORT ANFRAGEN", it = "CHIEDI SUPPORTO", es = "PEDIR SOPORTE", br = "PEDIR SUPORTE", pt = "PEDIR SUPORTE", ko = "지원 요청"),
    "Opens a game request with the ROM's file name and SHA-1 - never the ROM itself." to Tr(ja = "ROMの ファイルめいと SHA-1で ゲームの リクエストを ひらきます - ROMは おくりません。", fr = "Ouvre une demande de jeu avec le nom du fichier ROM et son SHA-1 - jamais la ROM.", de = "Öffnet eine Spielanfrage mit Dateiname und SHA-1 des ROMs - nie das ROM selbst.", it = "Apre una richiesta di gioco con nome file e SHA-1 della ROM - mai la ROM.", es = "Abre una solicitud de juego con el nombre y el SHA-1 de la ROM - nunca la ROM.", br = "Abre um pedido de jogo com o nome do arquivo e o SHA-1 da ROM - nunca a própria ROM.", pt = "Abre um pedido de jogo com o nome do ficheiro e o SHA-1 da ROM - nunca a própria ROM.", ko = "ROM의 파일 이름과 SHA-1로 게임 요청을 열어요. ROM 자체는 절대 보내지 않아요."),
    "THIS ROM ISN'T SUPPORTED" to Tr(ja = "この ROMには たいおう していません", fr = "CETTE ROM N'EST PAS PRISE EN CHARGE", de = "DIESE ROM WIRD NICHT UNTERSTÜTZT", it = "QUESTA ROM NON È SUPPORTATA", es = "ESTA ROM NO ES COMPATIBLE", br = "ESTA ROM NÃO É SUPORTADA", pt = "ESTA ROM NÃO É SUPORTADA", ko = "지원하지 않는 ROM"),
    "The game plays normally on the top screen, but the second screen can't read its party, map, items or battles." to Tr(ja = "ゲームは うえの がめんで ふつうに あそべますが 2つめの がめんでは てもち マップ どうぐ バトルを よみとれません。", fr = "Le jeu fonctionne normalement sur l'écran du haut, mais le second écran ne peut pas lire son équipe, sa carte, ses objets ni ses combats.", de = "Das Spiel läuft oben ganz normal, aber der zweite Bildschirm kann Team, Karte, Items und Kämpfe nicht lesen.", it = "Il gioco funziona normalmente sullo schermo superiore, ma il secondo schermo non può leggerne squadra, mappa, strumenti o lotte.", es = "El juego funciona con normalidad en la pantalla superior, pero la segunda pantalla no puede leer su equipo, mapa, objetos ni combates.", br = "O jogo funciona normalmente na tela de cima, mas a segunda tela não consegue ler a equipe, o mapa, os itens nem as batalhas.", pt = "O jogo funciona normalmente no ecrã de cima, mas o segundo ecrã não consegue ler a equipe, o mapa, os itens nem as batalhas.", ko = "게임은 위 화면에서 평소처럼 플레이할 수 있지만, 두 번째 화면은 파티, 지도, 도구, 배틀을 읽을 수 없어요."),
    "SETTINGS (the gear below) still works." to Tr(ja = "せってい (したの はぐるま) は つかえます。", fr = "OPTIONS (l'engrenage en bas) fonctionne toujours.", de = "OPTIONEN (das Zahnrad unten) funktioniert weiterhin.", it = "OPZIONI (l'ingranaggio in basso) funziona ancora.", es = "AJUSTES (el engranaje de abajo) sigue funcionando.", br = "CONFIGURAÇÕES (a engrenagem abaixo) continua funcionando.", pt = "DEFINIÇÕES (a engrenagem abaixo) continua a funcionar.", ko = "설정 (아래 톱니바퀴)은 그대로 쓸 수 있어요."),
    "no data yet" to Tr(ja = "まだ データが ありません", fr = "pas encore de données", de = "noch keine Daten", it = "ancora nessun dato", es = "aún no hay datos", br = "ainda sem dados", pt = "ainda sem dados", ko = "아직 데이터 없음"),
    "starting…" to Tr(ja = "じゅんびちゅう…", fr = "démarrage…", de = "startet…", it = "avvio…", es = "iniciando…", br = "iniciando…", pt = "a iniciar…", ko = "시작하는 중…"),

