    "Marks {0} as out of the run, as if it had fainted." to Tr(ja = "{0}が たおれた ことに して もう つかえなく します。", fr = "Retire {0} du défi, comme s'il avait été mis K.O.", de = "Lässt {0} ausscheiden, als wäre es besiegt worden.", it = "Mette {0} fuori dalla sfida, come se fosse esausto.", es = "Saca a {0} del reto, como si se hubiera debilitado.", br = "Tira {0} do desafio, como se tivesse desmaiado.", pt = "Tira {0} do desafio, como se tivesse desmaiado.", ko = "{0}, 기절한 것처럼 챌린지에서 빼요."),
    "ENCOUNTERS" to Tr(ja = "であい", fr = "RENCONTRES", de = "BEGEGNUNGEN", it = "INCONTRI", es = "ENCUENTROS", br = "ENCONTROS", pt = "ENCONTROS", ko = "만남"),
    "GRAVEYARD" to Tr(ja = "おはか", fr = "CIMETIÈRE", de = "FRIEDHOF", it = "CIMITERO", es = "CEMENTERIO", br = "CEMITÉRIO", pt = "CEMITÉRIO", ko = "묘지"),
    "Fainted in {0}" to Tr(ja = "{0}で たおれた", fr = "K.O. à {0}", de = "Besiegt in {0}", it = "Esausto a {0}", es = "Debilitado en {0}", br = "Desmaiou em {0}", pt = "Desmaiou em {0}", ko = "{0}에서 기절"),
    "BRING BACK {0}?" to Tr(ja = "{0}を もどす?", fr = "RAMENER {0} ?", de = "{0} ZURÜCKHOLEN?", it = "RIPORTARE {0}?", es = "¿RECUPERAR A {0}?", br = "TRAZER {0} DE VOLTA?", pt = "TRAZER {0} DE VOLTA?", ko = "{0}, 되돌릴까요?"),
    "Puts {0} back in the run, for a faint that shouldn't count." to Tr(ja = "かぞえない はずの ひんしなら {0}を もどします。", fr = "Remet {0} dans le défi, pour un K.O. qui ne devrait pas compter.", de = "Holt {0} in den Lauf zurück, für eine Niederlage, die nicht zählen soll.", it = "Rimette {0} nella sfida, per un esausto che non deve contare.", es = "Devuelve a {0} al reto, por un debilitamiento que no debería contar.", br = "Põe {0} de volta no desafio, para um desmaio que não devia contar.", pt = "Põe {0} de volta no desafio, para um desmaio que não devia contar.", ko = "세지 않아야 할 기절이었다면 챌린지로 되돌려요: {0}."),
    "RULES" to Tr(ja = "ルール", fr = "RÈGLES", de = "REGELN", it = "REGOLE", es = "REGLAS", br = "REGRAS", pt = "REGRAS", ko = "규칙"),
    "DUPES CLAUSE" to Tr(ja = "かぶり なし", fr = "CLAUSE DOUBLON", de = "DUPLIKAT-REGEL", it = "CLAUSOLA DOPPIONI", es = "CLÁUSULA REPETIDOS", br = "CLÁUSULA REPETIDOS", pt = "CLÁUSULA REPETIDOS", ko = "중복 조항"),
    "A POKéMON you've caught before doesn't use up an area" to Tr(ja = "つかまえた ことの ある ポケモンは かぞえない", fr = "Un POKéMON déjà capturé n'utilise pas la zone", de = "Ein schon gefangenes POKéMON verbraucht kein Gebiet", it = "Un POKéMON già catturato non consuma la zona", es = "Un POKéMON ya capturado no gasta la zona", br = "Um POKéMON já capturado não gasta a área", pt = "Um POKéMON já capturado não gasta a área", ko = "전에 잡은 포켓몬은 지역의 기회를 쓰지 않아요"),
    "WARNINGS" to Tr(ja = "おしらせ", fr = "AVERTISSEMENTS", de = "HINWEISE", it = "AVVISI", es = "AVISOS", br = "AVISOS", pt = "AVISOS", ko = "알림"),
    "Notices on the game screen as the run goes" to Tr(ja = "ゲームの がめんに おしらせを だす", fr = "Des messages sur l'écran du jeu pendant le défi", de = "Hinweise auf dem Spielbildschirm", it = "Messaggi sullo schermo del gioco durante la sfida", es = "Avisos en la pantalla del juego durante el reto", br = "Avisos na tela do jogo durante o desafio", pt = "Avisos no ecrã do jogo durante o desafio", ko = "챌린지 중 게임 화면에 알림 표시"),
    "NUZLOCKE tracking is off for this game. Turn it on and the companion keeps score of your run: only the first wild POKéMON in each area counts, and a POKéMON that faints is out for good." to Tr(ja = "この ゲームの ナズロックは オフです。 オンに すると コンパニオンが きろくを つけます: ばしょごとに さいしょの やせいの ポケモンだけ、 たおれた ポケモンは もう つかえません。", fr = "Le suivi NUZLOCKE est désactivé pour ce jeu. Activez-le et le compagnon tient le compte du défi : seul le premier POKéMON sauvage de chaque zone compte, et un POKéMON K.O. est perdu pour de bon.", de = "NUZLOCKE ist für dieses Spiel aus. Schalte es ein und der Begleiter führt Buch: Nur das erste wilde POKéMON jedes Gebiets zählt, und ein besiegtes POKéMON scheidet für immer aus.", it = "Il NUZLOCKE è disattivato per questo gioco. Attivalo e il compagno tiene il conto della sfida: conta solo il primo POKéMON selvatico di ogni zona, e un POKéMON esausto è fuori per sempre.", es = "El NUZLOCKE está desactivado en este juego. Actívalo y el compañero lleva la cuenta del reto: solo cuenta el primer POKéMON salvaje de cada zona, y un POKéMON debilitado queda fuera para siempre.", br = "O NUZLOCKE está desligado neste jogo. Ligue e o companheiro acompanha o desafio: só vale o primeiro POKéMON selvagem de cada área, e um POKéMON que desmaia sai de vez.", pt = "O NUZLOCKE está desligado neste jogo. Liga-o e o companheiro acompanha o desafio: só conta o primeiro POKéMON selvagem de cada área, e um POKéMON que desmaia sai de vez.", ko = "이 게임의 NUZLOCKE 기록이 꺼져 있어요. 켜면 컴패니언이 챌린지를 기록해요: 각 지역에서 처음 만난 야생 포켓몬만 인정되고, 기절한 포켓몬은 영영 탈락이에요."),
    "You can turn it off again in SETTINGS, under GAMEPLAY." to Tr(ja = "せっていの プレイで また オフに できます。", fr = "Vous pourrez le désactiver dans OPTIONS, sous GAMEPLAY.", de = "Ausschalten kannst du es unter OPTIONEN, GAMEPLAY.", it = "Puoi disattivarlo in OPZIONI, sotto GAMEPLAY.", es = "Puedes desactivarlo en AJUSTES, en JUGABILIDAD.", br = "Dá para desligar em CONFIGURAÇÕES, em JOGABILIDADE.", pt = "Podes desligá-lo nas DEFINIÇÕES, em JOGABILIDADE.", ko = "설정의 게임플레이에서 다시 끌 수 있어요."),
    "NEW RUN" to Tr(ja = "あたらしく はじめる", fr = "NOUVEAU DÉFI", de = "NEUER LAUF", it = "NUOVA SFIDA", es = "NUEVO RETO", br = "NOVO DESAFIO", pt = "NOVO DESAFIO", ko = "새 챌린지"),
    "NEW RUN?" to Tr(ja = "あたらしく はじめる?", fr = "NOUVEAU DÉFI ?", de = "NEUER LAUF?", it = "NUOVA SFIDA?", es = "¿NUEVO RETO?", br = "NOVO DESAFIO?", pt = "NOVO DESAFIO?", ko = "새 챌린지를 시작할까요?"),
    "Forgets every encounter and fainted POKéMON of this run. Your party right now starts the new one." to Tr(ja = "この チャレンジの であいと たおれた ポケモンを すべて わすれます。いまの てもちで あたらしく はじめます。", fr = "Oublie toutes les rencontres et les POKéMON K.O. de ce défi. Votre équipe actuelle commence le nouveau.", de = "Vergisst alle Begegnungen und besiegten POKéMON dieses Laufs. Dein jetziges Team beginnt den neuen.", it = "Dimentica tutti gli incontri e i POKéMON esausti di questa sfida. La tua squadra attuale inizia la nuova.", es = "Olvida todos los encuentros y POKéMON debilitados de este reto. Tu equipo actual empieza el nuevo.", br = "Esquece todos os encontros e POKéMON desmaiados deste desafio. Sua equipe atual começa o novo.", pt = "Esquece todos os encontros e POKéMON desmaiados deste desafio. A tua equipa atual começa o novo.", ko = "이번 챌린지의 만남과 기절한 포켓몬을 모두 잊어요. 지금 파티로 새 챌린지를 시작해요."),
    "PKMN DATA" to Tr(ja = "ポケモン データ", fr = "DONNÉES PKMN", de = "PKMN-DATEN", it = "DATI PKMN", es = "DATOS PKMN", br = "DADOS PKMN", pt = "DADOS PKMN", ko = "포켓몬 데이터"),
    "Swap {0} with which POKéMON?" to Tr(ja = "{0}と どの ポケモンを いれかえる?", fr = "Échanger {0} avec quel POKéMON ?", de = "{0} mit welchem POKéMON tauschen?", it = "Scambiare {0} con quale POKéMON?", es = "¿Cambiar {0} por qué POKéMON?", br = "Trocar {0} com qual POKéMON?", pt = "Trocar {0} com qual POKéMON?", ko = "{0}, 어느 포켓몬과 바꿀까요?"),
    "{0} joined the party and {1} went to {2}. Save in the game to keep it." to Tr(ja = "{0}が てもちに くわわり {1}は {2}へ。 のこすには ゲームで レポートを かいてね。", fr = "{0} rejoint l'équipe et {1} va dans {2}. Sauvegardez dans le jeu pour le garder.", de = "{0} ist jetzt im Team, {1} in {2}. Speichere im Spiel, um es zu behalten.", it = "{0} entra in squadra e {1} va in {2}. Salva nel gioco per tenerlo.", es = "{0} se une al equipo y {1} va a {2}. Guarda en el juego para conservarlo.", br = "{0} entrou na equipe e {1} foi para {2}. Salve no jogo para manter.", pt = "{0} entrou na equipa e {1} foi para {2}. Guarda no jogo para manter.", ko = "{0}, 파티에 합류했어요. {1}, {2}에 맡겼어요. 남기려면 게임에서 리포트를 쓰세요."),
    "The party or the box has changed. Try again." to Tr(ja = "てもちか ボックスが かわりました。 もういちど ためしてね。", fr = "L'équipe ou la boîte a changé. Réessayez.", de = "Team oder Box haben sich geändert. Versuch es noch mal.", it = "La squadra o il box sono cambiati. Riprova.", es = "El equipo o la caja ha cambiado. Inténtalo de nuevo.", br = "A equipe ou a caixa mudou. Tente de novo.", pt = "A equipa ou a caixa mudou. Tenta de novo.", ko = "파티나 박스가 바뀌었어요. 다시 해 주세요."),
    "Take the MAIL from {0} first." to Tr(ja = "さきに {0}の メールを はずしてね。", fr = "Retirez d'abord la LETTRE de {0}.", de = "Nimm {0} zuerst den BRIEF ab.", it = "Togli prima la LETTERA a {0}.", es = "Quítale antes la CARTA a {0}.", br = "Tire a CARTA de {0} primeiro.", pt = "Tira a CARTA de {0} primeiro.", ko = "먼저 {0}에게서 메일을 빼 주세요."),
    "An EGG can't take the place of your last POKéMON that can battle." to Tr(ja = "たたかえる さいごの ポケモンと タマゴは いれかえられない。", fr = "Un ŒUF ne peut pas remplacer votre dernier POKéMON en état de se battre.", de = "Ein EI kann dein letztes kampffähiges POKéMON nicht ersetzen.", it = "Un UOVO non può prendere il posto del tuo ultimo POKéMON in grado di lottare.", es = "Un HUEVO no puede ocupar el lugar de tu último POKéMON que puede luchar.", br = "Um OVO não pode tomar o lugar do seu último POKéMON que pode batalhar.", pt = "Um OVO não pode tomar o lugar do teu último POKéMON que pode lutar.", ko = "싸울 수 있는 마지막 포켓몬 자리에 알을 넣을 수 없어요."),
    "DEPOSIT" to Tr(ja = "あずける", fr = "DÉPOSER", de = "ABLEGEN", it = "DEPOSITA", es = "DEJAR", br = "DEPOSITAR", pt = "DEPOSITAR", ko = "맡기기"),
    "WITHDRAW" to Tr(ja = "つれていく", fr = "RETIRER", de = "MITNEHMEN", it = "PRENDI", es = "SACAR", br = "RETIRAR", pt = "RETIRAR", ko = "데려가기"),
    "FULL" to Tr(ja = "いっぱい", fr = "PLEINE", de = "VOLL", it = "PIENO", es = "LLENA", br = "CHEIA", pt = "CHEIA", ko = "가득 참"),
    "Deposit {0} in which BOX?" to Tr(ja = "{0}を どの ボックスに あずける?", fr = "Déposer {0} dans quelle BOÎTE ?", de = "{0} in welcher BOX ablegen?", it = "Depositare {0} in quale BOX?", es = "¿Dejar a {0} en qué CAJA?", br = "Depositar {0} em qual CAIXA?", pt = "Depositar {0} em qual CAIXA?", ko = "{0}, 어느 박스에 맡길까요?"),
    "Party full: swap {0} with which POKéMON?" to Tr(ja = "てもち いっぱい: {0}と どれを いれかえる?", fr = "Équipe pleine : échanger {0} avec quel POKéMON ?", de = "Team voll: {0} mit welchem POKéMON tauschen?", it = "Squadra piena: scambiare {0} con quale POKéMON?", es = "Equipo lleno: ¿cambiar {0} por qué POKéMON?", br = "Equipe cheia: trocar {0} com qual POKéMON?", pt = "Equipa cheia: trocar {0} com qual POKéMON?", ko = "파티가 가득 찼어요: {0}, 어느 포켓몬과 바꿀까요?"),
    "{0} was stored in {1}. Save in the game to keep it." to Tr(ja = "{0}を {1}に あずけた。 のこすには ゲームで レポートを かいてね。", fr = "{0} a été déposé dans {1}. Sauvegardez dans le jeu pour le garder.", de = "{0} ist jetzt in {1}. Speichere im Spiel, um es zu behalten.", it = "{0} è stato depositato in {1}. Salva nel gioco per tenerlo.", es = "{0} se ha dejado en {1}. Guarda en el juego para conservarlo.", br = "{0} foi depositado em {1}. Salve no jogo para manter.", pt = "{0} foi depositado em {1}. Guarda no jogo para manter.", ko = "{0}, {1}에 맡겼어요. 남기려면 게임에서 리포트를 쓰세요."),
    "{0} was taken out of {1} and joined the party. Save in the game to keep it." to Tr(ja = "{0}を {1}から つれていき てもちに くわえた。 のこすには ゲームで レポートを かいてね。", fr = "{0} a été retiré de {1} et rejoint l'équipe. Sauvegardez dans le jeu pour le garder.", de = "{0} kam aus {1} ins Team. Speichere im Spiel, um es zu behalten.", it = "{0} è stato preso da {1} ed entra in squadra. Salva nel gioco per tenerlo.", es = "{0} ha salido de {1} y se une al equipo. Guarda en el juego para conservarlo.", br = "{0} saiu de {1} e entrou na equipe. Salve no jogo para manter.", pt = "{0} saiu de {1} e entrou na equipa. Guarda no jogo para manter.", ko = "{0}, {1}에서 데려와 파티에 합류했어요. 남기려면 게임에서 리포트를 쓰세요."),
    "That's your last POKéMON that can battle!" to Tr(ja = "たたかえる さいごの ポケモンです!", fr = "C'est votre dernier POKéMON en état de se battre !", de = "Das ist dein letztes kampffähiges POKéMON!", it = "È il tuo ultimo POKéMON in grado di lottare!", es = "¡Es tu último POKéMON que puede luchar!", br = "É o seu último POKéMON que pode batalhar!", pt = "É o teu último POKéMON que pode lutar!", ko = "싸울 수 있는 마지막 포켓몬이에요!"),
    "{0} is full." to Tr(ja = "{0}は いっぱいです。", fr = "{0} est pleine.", de = "{0} ist voll.", it = "{0} è pieno.", es = "{0} está llena.", br = "{0} está cheia.", pt = "{0} está cheia.", ko = "{0}: 가득 찼어요."),
    "Your party is full!" to Tr(ja = "てもちが いっぱいです!", fr = "Votre équipe est pleine !", de = "Dein Team ist voll!", it = "La tua squadra è piena!", es = "¡Tu equipo está lleno!", br = "Sua equipe está cheia!", pt = "A tua equipa está cheia!", ko = "파티가 가득 찼어요!"),
    "That didn't work. Nothing was changed." to Tr(ja = "うまく いかなかった。 なにも かわっていません。", fr = "Ça n'a pas marché. Rien n'a changé.", de = "Das hat nicht geklappt. Nichts wurde geändert.", it = "Non è riuscito. Non è cambiato nulla.", es = "No ha funcionado. No se ha cambiado nada.", br = "Não funcionou. Nada foi alterado.", pt = "Não funcionou. Nada foi alterado.", ko = "실패했어요. 아무것도 바뀌지 않았어요."),
    "The swap didn't work. Nothing was changed." to Tr(ja = "いれかえられなかった。 なにも かわっていません。", fr = "L'échange n'a pas marché. Rien n'a changé.", de = "Der Tausch hat nicht geklappt. Nichts wurde geändert.", it = "Lo scambio non è riuscito. Non è cambiato nulla.", es = "El cambio no ha funcionado. No se ha cambiado nada.", br = "A troca não funcionou. Nada foi alterado.", pt = "A troca não funcionou. Nada foi alterado.", ko = "교체에 실패했어요. 아무것도 바뀌지 않았어요."),
    "Pick a box" to Tr(ja = "ボックスを えらぶ", fr = "Choisir une boîte", de = "Box wählen", it = "Scegli un box", es = "Elegir una caja", br = "Escolher uma caixa", pt = "Escolher uma caixa", ko = "박스 선택"),
    "NUZLOCKE" to Tr(ja = "ナズロック", fr = "NUZLOCKE", de = "NUZLOCKE", it = "NUZLOCKE", es = "NUZLOCKE", br = "NUZLOCKE", pt = "NUZLOCKE", ko = "NUZLOCKE"),
    "{0} ALIVE · {1} FAINTED" to Tr(ja = "げんき {0} · ひんし {1}", fr = "{0} EN VIE · {1} TOMBÉS", de = "{0} FIT · {1} BESIEGT", it = "{0} VIVI · {1} CADUTI", es = "{0} EN PIE · {1} CAÍDOS", br = "{0} VIVOS · {1} CAÍDOS", pt = "{0} VIVOS · {1} CAÍDOS", ko = "생존 {0} · 기절 {1}"),
    "NOT USED" to Tr(ja = "つかって いない", fr = "NON UTILISÉ", de = "UNBENUTZT", it = "NON USATO", es = "SIN USAR", br = "NÃO USADO", pt = "NÃO USADO", ko = "미사용"),
    "With you from the start" to Tr(ja = "さいしょから いっしょ", fr = "Avec vous depuis le début", de = "Von Anfang an dabei", it = "Con te dall'inizio", es = "Contigo desde el principio", br = "Com você desde o início", pt = "Contigo desde o início", ko = "처음부터 함께"),
    "Joined in {0}" to Tr(ja = "{0}で なかまに なった", fr = "Arrivé à {0}", de = "Dazugekommen in {0}", it = "Arrivato a {0}", es = "Se unió en {0}", br = "Entrou em {0}", pt = "Entrou em {0}", ko = "{0}에서 합류"),
    "Out of the run" to Tr(ja = "もう つかえない", fr = "Hors du défi", de = "Ausgeschieden", it = "Fuori dalla sfida", es = "Fuera del reto", br = "Fora do desafio", pt = "Fora do desafio", ko = "챌린지 탈락"),
    "Track a run: one catch per area, a faint is final" to Tr(ja = "1ばしょ 1ぴき、ひんしは さいごの チャレンジを きろく", fr = "Suivez un défi : une capture par zone, un K.O. est définitif", de = "Verfolge einen Lauf: ein Fang pro Gebiet, besiegt ist endgültig", it = "Segui una sfida: una cattura per zona, chi è esausto è perso", es = "Sigue un reto: una captura por zona, debilitarse es definitivo", br = "Acompanhe um desafio: uma captura por área, desmaiar é para sempre", pt = "Acompanha um desafio: uma captura por área, desmaiar é para sempre", ko = "챌린지 기록: 지역마다 한 마리, 기절하면 끝"),
    // Feature tips (FeatureTip.kt): the card over the game / on the companion.
    "ENJOYED THE VIEW?" to Tr(ja = "けしきは どうだった?", fr = "BELLE VUE, NON ?", de = "SCHÖNE AUSSICHT?", it = "BEL PANORAMA?", es = "¿TE GUSTÓ LA VISTA?", br = "CURTIU A VISTA?", pt = "GOSTASTE DA VISTA?", ko = "풍경 어땠어요?"),
    "FLY now takes you there over the map. Keep it, or use the classic FLY. Change it any time in SETTINGS > FLY STYLE." to Tr(ja = "そらをとぶで マップの うえを とんでいく。 このままか クラシックか えらんでね。 せってい > そらをとぶの みため で かえられる。", fr = "VOL vous y emmène en survolant la carte. Gardez-le, ou prenez le VOL classique. Modifiable dans OPTIONS > STYLE DE VOL.", de = "FLIEGEN bringt dich jetzt über die Karte hin. Behalte es oder nimm das klassische. Änderbar unter OPTIONEN > FLUGSTIL.", it = "VOLO ora ti porta lì sorvolando la mappa. Tienilo, o usa il VOLO classico. Cambialo in OPZIONI > STILE VOLO.", es = "VUELO te lleva volando sobre el mapa. Mantenlo o usa el VUELO clásico. Cámbialo en AJUSTES > ESTILO DE VUELO.", br = "VOAR leva você voando sobre o mapa. Mantenha, ou use o VOAR clássico. Mude em CONFIGURAÇÕES > ESTILO DE VOO.", pt = "VOAR leva-te a voar sobre o mapa. Mantém, ou usa o VOAR clássico. Muda em DEFINIÇÕES > ESTILO DE VOO.", ko = "이제 공중날기가 맵 위를 날아서 가요. 그대로 쓰거나 클래식으로 바꿀 수 있어요. 설정 > 공중날기 스타일에서 언제든 바꿔요."),
    "KEEP IT" to Tr(ja = "このまま", fr = "LE GARDER", de = "BEHALTEN", it = "TIENILO", es = "MANTENER", br = "MANTER", pt = "MANTER", ko = "그대로"),
    "USE CLASSIC" to Tr(ja = "クラシックに", fr = "CLASSIQUE", de = "KLASSISCH", it = "CLASSICO", es = "CLÁSICO", br = "CLÁSSICO", pt = "CLÁSSICO", ko = "클래식으로"),
    "ZOOM OUT, LOOK AROUND" to Tr(ja = "ズームして みまわそう", fr = "DÉZOOMEZ, REGARDEZ AUTOUR", de = "HERAUSZOOMEN, UMSEHEN", it = "ALLONTANA E GUARDATI INTORNO", es = "ALEJA Y MIRA ALREDEDOR", br = "AFASTE E OLHE AO REDOR", pt = "AFASTE E OLHE À VOLTA", ko = "줌 아웃, 둘러보기"),
    "With EXPAND you can see further than the game ever showed you." to Tr(ja = "ひろげる なら ゲームが みせなかった ところまで みえる。", fr = "Avec ÉTENDRE, vous voyez plus loin que le jeu ne l'a jamais montré.", de = "Mit ERWEITERN siehst du weiter, als das Spiel je gezeigt hat.", it = "Con ESPANDI vedi più lontano di quanto il gioco abbia mai mostrato.", es = "Con AMPLIAR ves más lejos de lo que el juego mostró nunca.", br = "Com EXPANDIR você vê mais longe do que o jogo já mostrou.", pt = "Com EXPANDIR vê mais longe do que o jogo alguma vez mostrou.", ko = "확장을 켜면 게임이 보여 준 것보다 더 멀리 볼 수 있어요."),
    "TRIGGERS IN DS GAMES" to Tr(ja = "DSの ゲームの トリガー", fr = "GÂCHETTES EN JEU DS", de = "TRIGGER IN DS-SPIELEN", it = "GRILLETTI NEI GIOCHI DS", es = "GATILLOS EN JUEGOS DS", br = "GATILHOS NOS JOGOS DE DS", pt = "GATILHOS NOS JOGOS DE DS", ko = "DS 게임의 트리거"),
    "A DS game on one screen keeps its touch screen out of the way. Your triggers bring it in and change how the two screens sit." to Tr(ja = "ひとつの がめんでは DSの タッチがめんは かくれています。 トリガーで よびだしたり 2つの がめんの ならびを かえたり できます。", fr = "Sur un seul écran, un jeu DS garde son écran tactile de côté. Vos gâchettes le font venir et changent la place des deux écrans.", de = "Auf einem Bildschirm hält ein DS-Spiel seinen Touchscreen aus dem Weg. Deine Trigger holen ihn her und ändern, wie die zwei Bildschirme liegen.", it = "Su uno schermo, un gioco DS tiene da parte il touch screen. I grilletti lo fanno apparire e cambiano come stanno i due schermi.", es = "En una sola pantalla, un juego de DS aparta su pantalla táctil. Tus gatillos la traen y cambian cómo se colocan las dos pantallas.", br = "Em uma tela só, um jogo de DS deixa a tela de toque de lado. Seus gatilhos trazem ela e mudam como as duas telas ficam.", pt = "Num só ecrã, um jogo de DS deixa o ecrã tátil de lado. Os teus gatilhos trazem-no e mudam a forma como os dois ecrãs ficam.", ko = "한 화면에서는 DS 게임의 터치 화면이 비켜 있어요. 트리거로 불러오고 두 화면의 배치를 바꿀 수 있어요."),
    "NEXT LAYOUT" to Tr(ja = "つぎの ならび", fr = "DISPOSITION SUIVANTE", de = "NÄCHSTES LAYOUT", it = "LAYOUT SUCCESSIVO", es = "SIGUIENTE DISEÑO", br = "PRÓXIMO LAYOUT", pt = "DISPOSIÇÃO SEGUINTE", ko = "다음 배치"),
    "SHOW ME" to Tr(ja = "みせて", fr = "MONTRER", de = "ZEIG MAL", it = "MOSTRA", es = "VER", br = "MOSTRAR", pt = "MOSTRAR", ko = "보기"),
    "SEE MORE OF THE WORLD" to Tr(ja = "せかいを もっと みよう", fr = "VOYEZ PLUS DU MONDE", de = "SIEH MEHR VON DER WELT", it = "VEDI PIÙ MONDO", es = "VE MÁS DEL MUNDO", br = "VEJA MAIS DO MUNDO", pt = "VEJA MAIS DO MUNDO", ko = "더 넓은 세상 보기"),
    "EXPAND draws the map past the game's edges, so the whole screen is the game. No black bars, nothing stretched." to Tr(ja = "ひろげるは ゲームの はしの そとまで マップを えがく。 がめん ぜんぶが ゲームに なる。 くろい おびも のびも なし。", fr = "ÉTENDRE dessine la carte au-delà des bords du jeu : tout l'écran devient le jeu. Ni bandes noires, ni étirement.", de = "ERWEITERN zeichnet die Karte über den Rand des Spiels hinaus, der ganze Bildschirm ist Spiel. Keine schwarzen Balken, nichts verzerrt.", it = "ESPANDI disegna la mappa oltre i bordi del gioco: tutto lo schermo è il gioco. Niente bande nere, niente stirato.", es = "AMPLIAR dibuja el mapa más allá de los bordes del juego: toda la pantalla es el juego. Sin barras negras ni estirar.", br = "EXPANDIR desenha o mapa além das bordas do jogo: a tela toda é o jogo. Sem barras pretas, nada esticado.", pt = "EXPANDIR desenha o mapa para lá das margens do jogo: o ecrã todo é o jogo. Sem barras pretas, nada esticado.", ko = "확장은 게임 가장자리 너머까지 지도를 그려서 화면 전체가 게임이 돼요. 검은 여백도, 늘어난 화면도 없어요."),
    "EVERYTHING IN ONE PRESS" to Tr(ja = "ボタン ひとつで なんでも", fr = "TOUT EN UNE PRESSION", de = "ALLES MIT EINEM DRUCK", it = "TUTTO CON UN TASTO", es = "TODO CON UN BOTÓN", br = "TUDO NUM BOTÃO", pt = "TUDO NUM BOTÃO", ko = "버튼 하나로 모두"),
    "The QUICK MENU opens the PC, flies, gets on your bike or saves a state without leaving the field." to Tr(ja = "クイックメニューで パソコン そらをとぶ じてんしゃ ステート セーブが その ばで できる。", fr = "Le MENU RAPIDE ouvre le PC, fait voler, sort le vélo ou sauve un état sans quitter la carte.", de = "Das SCHNELLMENÜ öffnet den PC, fliegt, holt das Rad oder sichert einen Spielstand, direkt unterwegs.", it = "Il MENU RAPIDO apre il PC, vola, prende la bici o salva uno stato senza lasciare la mappa.", es = "El MENÚ RÁPIDO abre el PC, vuela, saca la bici o guarda un estado sin salir del mapa.", br = "O MENU RÁPIDO abre o PC, voa, pega a bicicleta ou salva um estado sem sair do mapa.", pt = "O MENU RÁPIDO abre o PC, voa, tira a bicicleta ou guarda um estado sem sair do mapa.", ko = "퀵 메뉴로 필드를 떠나지 않고 PC 열기, 공중날기, 자전거 타기, 스테이트 세이브를 할 수 있어요."),
    "OPEN IT" to Tr(ja = "ひらく", fr = "OUVRIR", de = "ÖFFNEN", it = "APRI", es = "ABRIR", br = "ABRIR", pt = "ABRIR", ko = "열기"),
    "TAP THE HUD" to Tr(ja = "HUDを タッチ", fr = "TOUCHEZ LE HUD", de = "TIPP AUFS HUD", it = "TOCCA L'HUD", es = "TOCA EL HUD", br = "TOQUE NO HUD", pt = "TOQUE NO HUD", ko = "HUD 탭하기"),
    "Tap a party icon for its summary, the minimap for the map, BAG to use an item." to Tr(ja = "てもちの アイコンで ようす ミニマップで マップ バッグで どうぐを つかえる。", fr = "Touchez une icône de l'équipe pour son résumé, la mini carte pour la carte, SAC pour utiliser un objet.", de = "Tipp ein Teamsymbol für die Übersicht, die Minikarte für die Karte, BEUTEL für ein Item.", it = "Tocca un'icona della squadra per il riepilogo, la minimappa per la mappa, BORSA per usare uno strumento.", es = "Toca un icono del equipo para su resumen, el minimapa para el mapa, MOCHILA para usar un objeto.", br = "Toque num ícone da equipe para o resumo, no minimapa para o mapa, em MOCHILA para usar um item.", pt = "Toque num ícone da equipe para o resumo, no minimapa para o mapa, em MOCHILA para usar um item.", ko = "파티 아이콘을 탭하면 요약, 미니맵은 지도, 가방은 도구 사용이에요."),
    "THE PC, FROM ANYWHERE" to Tr(ja = "どこでも パソコン", fr = "LE PC, OÙ QUE VOUS SOYEZ", de = "DER PC, ÜBERALL", it = "IL PC, OVUNQUE", es = "EL PC, DONDE SEA", br = "O PC, DE QUALQUER LUGAR", pt = "O PC, EM QUALQUER LADO", ko = "어디서나 PC"),
    "Open your boxes from the BAG tab or the QUICK MENU. No walk back to town." to Tr(ja = "バッグか クイックメニューから ボックスを ひらける。 まちまで もどらなくて いい。", fr = "Ouvrez vos boîtes depuis l'onglet SAC ou le MENU RAPIDE. Plus besoin de rentrer en ville.", de = "Öffne deine Boxen über BEUTEL oder das SCHNELLMENÜ. Kein Weg zurück in die Stadt.", it = "Apri i box dalla scheda BORSA o dal MENU RAPIDO. Niente ritorno in città.", es = "Abre tus cajas desde MOCHILA o el MENÚ RÁPIDO. Sin volver a la ciudad.", br = "Abra suas caixas pela MOCHILA ou pelo MENU RÁPIDO. Sem voltar à cidade.", pt = "Abra as suas caixas pela MOCHILA ou pelo MENU RÁPIDO. Sem voltar à cidade.", ko = "가방 탭이나 퀵 메뉴에서 박스를 열어요. 마을로 돌아갈 필요 없어요."),
    "OPEN PC" to Tr(ja = "パソコンを ひらく", fr = "OUVRIR LE PC", de = "PC ÖFFNEN", it = "APRI IL PC", es = "ABRIR PC", br = "ABRIR PC", pt = "ABRIR PC", ko = "PC 열기"),
    "NO NEED TO HOLD B" to Tr(ja = "Bを おさなくて いい", fr = "PLUS BESOIN DE TENIR B", de = "B NICHT MEHR HALTEN", it = "NON SERVE TENERE B", es = "SIN MANTENER B", br = "SEM SEGURAR B", pt = "SEM MANTER B", ko = "B를 누르고 있을 필요 없음"),
    "AUTO-RUN makes you run on the field by itself. Hold B when you want to walk." to Tr(ja = "オートダッシュで いつでも はしる。 あるきたい ときは Bを おす。", fr = "COURSE AUTO vous fait courir tout seul. Maintenez B pour marcher.", de = "AUTO-RENNEN lässt dich von selbst rennen. Halte B, um zu gehen.", it = "CORSA AUTO ti fa correre da solo. Tieni premuto B per camminare.", es = "CORRER AUTO te hace correr solo. Mantén B para caminar.", br = "CORRIDA AUTO faz você correr sozinho. Segure B para andar.", pt = "CORRIDA AUTO faz você correr sozinho. Mantenha B para andar.", ko = "자동 달리기를 켜면 필드에서 저절로 달려요. 걷고 싶을 땐 B를 누르고 있으세요."),
    "TIRED OF WILD BATTLES?" to Tr(ja = "やせいの バトルに つかれた?", fr = "MARRE DES COMBATS SAUVAGES ?", de = "GENUG VON WILDEN KÄMPFEN?", it = "STANCO DEI SELVATICI?", es = "¿HARTO DE LOS SALVAJES?", br = "CANSADO DE BATALHAS SELVAGENS?", pt = "FARTO DE BATALHAS SELVAGENS?", ko = "야생 배틀이 지겹나요?"),
    "Switch wild encounters off for a while. Fishing and story battles still happen." to Tr(ja = "やせいの ポケモンを しばらく オフに。 つりと イベントの バトルは そのまま。", fr = "Coupez les POKéMON SAUVAGES un moment. La pêche et les combats de l'histoire restent.", de = "Schalte WILDE POKéMON eine Weile ab. Angeln und Kämpfe der Geschichte bleiben.", it = "Spegni i POKéMON SELVATICI per un po'. Pesca e lotte della storia restano.", es = "Apaga los POKéMON SALVAJES un rato. La pesca y los combates de la historia siguen.", br = "Desligue os POKéMON SELVAGENS por um tempo. Pesca e batalhas da história continuam.", pt = "Desligue os POKéMON SELVAGENS por um tempo. Pesca e batalhas da história continuam.", ko = "잠시 야생 포켓몬 출현을 꺼 보세요. 낚시와 스토리 배틀은 그대로 있어요."),
    "SWITCH OFF" to Tr(ja = "オフにする", fr = "COUPER", de = "ABSCHALTEN", it = "SPEGNI", es = "APAGAR", br = "DESLIGAR", pt = "DESLIGAR", ko = "끄기"),
    "KEEP YOUR TMS" to Tr(ja = "わざマシンを なくさない", fr = "GARDEZ VOS CT", de = "BEHALTE DEINE TM", it = "TIENI LE MT", es = "CONSERVA TUS MT", br = "GUARDE SEUS MTs", pt = "GUARDE OS SEUS MTs", ko = "기술머신을 계속 쓰기"),
    "With REUSABLE TMS a TM stays in your bag after it teaches a move." to Tr(ja = "マシン むげん なら おしえた あとも わざマシンが バッグに のこる。", fr = "Avec CT ILLIMITÉES, une CT reste dans le sac après usage.", de = "Mit TM BLEIBEN bleibt eine TM nach dem Lehren im Beutel.", it = "Con MT ILLIMITATE una MT resta nella borsa dopo l'uso.", es = "Con MT ILIMITADAS una MT sigue en la mochila tras usarla.", br = "Com MT ILIMITADOS um MT fica na mochila depois de usado.", pt = "Com MT ILIMITADOS um MT fica na mochila depois de usado.", ko = "재사용 기술머신을 켜면 기술을 가르친 뒤에도 기술머신이 가방에 남아요."),
    "FLY WITHOUT THE MENUS" to Tr(ja = "メニュー なしで そらをとぶ", fr = "VOLER SANS LES MENUS", de = "FLIEGEN OHNE MENÜS", it = "VOLA SENZA MENU", es = "VUELA SIN MENÚS", br = "VOE SEM MENUS", pt = "VOE SEM MENUS", ko = "메뉴 없이 공중날기"),
    "Pick a town you've been to and fly there: FLY on the MAP, or in the QUICK MENU." to Tr(ja = "いった まちを えらんで ひとっとび。 マップか クイックメニューの そらをとぶで。", fr = "Choisissez une ville déjà visitée et volez-y : VOL sur la CARTE ou dans le MENU RAPIDE.", de = "Wähle eine besuchte Stadt und flieg hin: FLIEGEN auf der KARTE oder im SCHNELLMENÜ.", it = "Scegli una città già visitata e volaci: VOLO sulla MAPPA o nel MENU RAPIDO.", es = "Elige una ciudad visitada y vuela allí: VUELO en el MAPA o en el MENÚ RÁPIDO.", br = "Escolha uma cidade visitada e voe até lá: VOAR no MAPA ou no MENU RÁPIDO.", pt = "Escolha uma cidade visitada e voe até lá: VOAR no MAPA ou no MENU RÁPIDO.", ko = "가 본 마을을 골라 날아가요: 지도의 공중날기나 퀵 메뉴에서."),
    "FLY NOW" to Tr(ja = "そらをとぶ", fr = "VOLER", de = "FLIEGEN", it = "VOLA", es = "VOLAR", br = "VOAR", pt = "VOAR", ko = "지금 날기"),
    "RIGHT STICK" to Tr(ja = "みぎスティック", fr = "STICK DROIT", de = "RECHTER STICK", it = "STICK DESTRO", es = "STICK DERECHO", br = "ANALÓGICO DIREITO", pt = "ANALÓGICO DIREITO", ko = "오른쪽 스틱"),
    "LOOK AROUND" to Tr(ja = "みまわす", fr = "REGARDER", de = "UMSEHEN", it = "GUARDA INTORNO", es = "MIRAR", br = "OLHAR", pt = "OLHAR", ko = "둘러보기"),
)
